const payload = $input.first().json;
const ticker = payload.ticker || 'NVDA';
const marketPrice = payload.marketPrice || 118.5;
const fcfPerShare = payload.fcfPerShare || 3.42;
const growthRate = payload.growthRate || 0.18;
const discountRate = 0.09;
const terminalGrowth = 0.03;

// 2-stage DCF model
let dcfValue = 0;
let fcf = fcfPerShare;
for (let yr = 1; yr <= 5; yr++) {
  fcf *= (1 + growthRate);
  dcfValue += fcf / Math.pow(1 + discountRate, yr);
}
const terminalValue = (fcf * (1 + terminalGrowth)) / (discountRate - terminalGrowth);
dcfValue += terminalValue / Math.pow(1 + discountRate, 5);
const intrinsicValue = Math.round(dcfValue * 100) / 100;
const marginOfSafety = Math.round(((intrinsicValue - marketPrice) / intrinsicValue) * 1000) / 10;

return {
  json: {
    ticker,
    marketPrice,
    intrinsicValue,
    marginOfSafety,
    peRatio: payload.peRatio || 36.4,
    piotroskiScore: 8,
    action: marginOfSafety > 10 ? 'BUY' : marginOfSafety < -15 ? 'SELL' : 'HOLD'
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'fundamental-valuation',
    botName: 'Fundamental Valuation & SEC 10-K RAG Agent',
    valuationReport: text,
    recommendation: 'STRONG_BUY_UNDERVALUED',
    timestamp: new Date().toISOString()
  }
};
